window.LUMINA_B = [{"pmid":"42988646","theme":"odontologie","genere":"2026-11-08","par":"Claude","pertinent":true,"raison_exclusion":"","a_verifier":["Âge des patients (13 à 24 ans) : le titre parle d'adolescents, la population est en partie adulte.","Sens exact de la résorption plus marquée sur deux dents (12 et 21) dans le groupe laser."],"texte_integral":false,"fiche":{"pmid":"42988646","title_fr":"Laser basse énergie 980 nm contre sham : résorption radiculaire et douleur sous appareil orthodontique fixe","type":"rct","level":2,"pop":"mixte","ctx":["ortho"],"aim":"les deux","mode":["laser"],"nm":[980],"n":40,"effect":"mitigé","theme":"Douleur orthodontique","l1":"Le laser 980 nm (8 J/cm²) ne limite pas la résorption radiculaire et n'accélère pas l'alignement, mais réduit nettement la douleur des premiers jours (p < 0,001).","l2":"Essai randomisé en double aveugle contre laser factice, monocentrique, chez 40 patients de 13 à 24 ans traités par appareil fixe. Laser diode 980 nm, 100 mW, 8 J/cm², 8 s par dent sur les incisives maxillaires, à J0, J3, J7, J14 puis chaque mois pendant 12 mois.\n\nLa résorption radiculaire (radiographies rétro-alvéolaires à 6 et 12 mois) progresse dans les deux groupes sans différence, sauf sur deux dents où elle est plus marquée sous laser. La douleur (EVA) est plus faible sous laser pendant la première semaine de nivellement et de rétraction. La durée de nivellement ne change pas (124 contre 126 jours).","l3":{"points":["Randomisation par blocs 1:1, double aveugle.","Protocole long : séances répétées sur 12 mois.","Effet antalgique net sur les 7 premiers jours, sauf à J5–J6.","Pas de gain sur la vitesse de déplacement."],"limites":["Petit effectif, centre unique.","Résorption mesurée en 2D sur radiographies rétro-alvéolaires.","Population mêlant adolescents et jeunes adultes."],"pratique":"Utile comme antalgique non médicamenteux en début de traitement ; ne pas en attendre de protection radiculaire ni d'accélération."}},"title":"Effect of low-level laser therapy versus sham laser in reduction of orthodontically induced inflammatory root resorption in the adolescent patients undergoing fixed orthodontic treatment: A randomized controlled trial.","journal":"J World Fed Orthod","date":"2026-11-05","doi":"10.1016/j.ejwf.2026.08.003","abstract":[{"label":"BACKGROUND","text":"This study evaluated the effect of low-level laser therapy (LLLT) on orthodontically induced inflammatory root resorption (OIIRR) during leveling and alignment and en-masse retraction in orthodontic patients. It also compared pain perception and treatment duration between LLLT and control groups."},{"label":"METHODS","text":"This single-center, double-blinded randomized controlled trial enrolled 40 adolescent patients aged 13 to 24 years (LLLT: 17.2 ± 3.0 years; control: 18.4 ± 3.1 years), allocated 1:1 via block randomization. Group I received LLLT (980 nm diode laser; 100 mW; 8 J/cm2; 8 s/tooth) to maxillary incisors on days 0, 3, 7, 14, and monthly for 12 months; Group II received sham laser. OIIRR was assessed via root length on periapical radiographs at baseline (T0), 6 months (T1), and 12 months (T2). Pain was recorded using the Visual Analogue Scale during the first 7 days of leveling and alignment (P1) and en-masse retraction (P2). Repeated measures ANOVA with Bonferroni posthoc and unpaired t-tests were used for intra and intergroup comparisons."},{"label":"RESULTS","text":"Significant root resorption occurred from T0 to T2 in both groups. No intergroup differences occurred except at tooth 12 (T0-T1) and 21 (T0-T2), where LLLT patients showed greater resorption (P < 0.05). LLLT significantly reduced pain at P1 and P2 (P < 0.001), except on days 5 to 6 at P1. Leveling and alignment duration did not differ between groups (123.8 vs. 126.2 days; P = 0.487)."},{"label":"CONCLUSION","text":"LLLT did not reduce OIIRR or shorten leveling and alignment duration but significantly attenuated short-term pain, supporting its use as a nonpharmacological analgesic adjunct in orthodontics."}]},{"pmid":"42982684","theme":"orl","genere":"2026-11-08","par":"Claude","pertinent":true,"raison_exclusion":"","a_verifier":["Puissance et dose par point exactes (30 J au total ?) à vérifier dans le texte intégral.","Perdus de vue : 39 analysées sur 46 incluses."],"texte_integral":false,"fiche":{"pmid":"42982684","title_fr":"Laser basse énergie ajouté à la rééducation vocale dans la dysphonie comportementale de la femme : essai en triple aveugle","type":"rct","level":2,"pop":"adulte","ctx":["pharynx"],"aim":"traitement","mode":["laser"],"nm":[808],"n":46,"effect":"neutre","theme":"Gorge, amygdales & voix","l1":"Ajouter un laser infrarouge 808 nm à la rééducation vocale n'améliore ni la voix perçue ni l'auto-évaluation par rapport au placebo ; seul l'aspect du bord des cordes vocales récupère mieux.","l2":"Essai randomisé en triple aveugle contre laser placebo chez 46 femmes de 18 à 60 ans atteintes de dysphonie comportementale (39 analysées à 8 semaines). Laser infrarouge 808 nm, 100 mW, 30 J, appliqué avant chaque séance d'un programme complet de rééducation vocale.\n\nLes deux groupes s'améliorent nettement (sévérité perçue, mesures acoustiques, auto-évaluation), sans différence entre eux pour le critère principal ni pour les critères fonctionnels. En vidéostroboscopie, le contour du bord libre des cordes vocales récupère davantage sous laser actif (p = 0,005). Aucun effet indésirable.","l3":{"points":["Triple aveugle, laser placebo.","Critère principal : sévérité globale perçue de la dysphonie.","Effet morphologique isolé sans traduction fonctionnelle.","Bonne tolérance."],"limites":["Effectif modeste, 15 % de perdus de vue.","Analyse per protocole.","Suivi limité à 8 semaines."],"pratique":"La rééducation vocale reste le traitement de fond ; le laser n'apporte pas de bénéfice fonctionnel démontré en complément."}},"title":"Efficacy of Voice Therapy Combined with Photobiomodulation in Women with Behavioral Dysphonia: A Triple-Blind Randomized Controlled Trial.","journal":"J Voice","date":"2026-11-04","doi":"10.1016/j.jvoice.2026.10.017","abstract":[{"label":"OBJECTIVES","text":"To investigate whether active low-level laser therapy (LLLT) provides an incremental effect as an adjunct to a comprehensive voice therapy (VT) program, compared to VT combined with a placebo laser therapy (PLT), in women with dysphonia."},{"label":"METHODS","text":"This prospective, parallel-group, triple-blind, placebo-controlled clinical trial enrolled 46 women (18-60 years), with 39 completing the 8-week per-protocol analysis (VT-LLLT n = 22; VT-PLT n = 17). The experimental group received infrared LLLT (808 nm, 100 mW, 30 J) prior to VT, while the control group received a placebo laser. The primary outcome was the auditory-perceptual overall severity (OS) of dysphonia. Secondary outcomes included acoustic measures, vocal self-assessment, and laryngeal videostroboscopic parameters."},{"label":"RESULTS","text":"Both groups demonstrated significant pre-to-post improvements across auditory-perceptual, self-assessment, and acoustic parameters, with no statistically significant Group × Time interaction for the primary outcome (OS) or any secondary functional variable. Conversely, laryngeal imaging evaluated via Generalized Linear Models (GLM) revealed a statistically significant Group × Time interaction for the recovery of the vocal fold edge contour (P = 0.005), indicating a localized morphological improvement in the VT-LLLT group. No adverse events were associated with the interventions."},{"label":"CONCLUSION","text":"Although adjunctive active LLLT significantly accelerates the localized macroscopic restoration of the vocal fold edge contour, this structural change does not translate into superior functional, acoustic, or perceptual voice outcomes compared to placebo. Behavioral VT unequivocally remains the primary and dominant therapeutic driver for functional vocal recovery in women with dysphonia."}]},{"pmid":"42905344","theme":"dermatologie","genere":"2026-11-08","par":"Claude","pertinent":false,"raison_exclusion":"Douleur chronique d'épaule chez la personne âgée : l'étude relève du thème musculo-squelettique (épaule), pas de la dermatologie ; la thermographie cutanée n'y est qu'un outil de mesure.","a_verifier":["Si l'étude est gardée, la rattacher au thème musculo-squelettique (sous-groupe épaule)."],"texte_integral":false,"fiche":{"pmid":"42905344","title_fr":"Laser-acupuncture auriculaire contre acupression par graines dans la douleur chronique d'épaule du sujet âgé (étude exploratoire)","type":"nrct","level":3,"pop":"adulte","ctx":["inflammatoire"],"aim":"traitement","mode":["laser-acupuncture"],"nm":[],"n":20,"effect":"neutre","theme":"Laser-acupuncture","l1":"Chez 20 personnes âgées douloureuses de l'épaule, la laser-acupuncture auriculaire et l'acupression par graines réduisent la douleur d'environ 2,5 points sur 10, sans différence entre elles.","l2":"Étude exploratoire non randomisée, en ouvert, avec deux cohortes successives de 10 patients de 60 à 90 ans : laser-acupuncture auriculaire ou graines d'acupression, deux fois par semaine pendant cinq semaines.\n\nL'EVA baisse de 2,7 points sous laser et de 2,5 sous graines (différence 0,2 point, IC 95 % −2,5 à 2,1). Quelques dimensions du McGill et du SF-36 évoluent ; la thermographie montre des variations de température propres à certaines régions de l'épaule.","l3":{"points":["Comparaison de deux techniques auriculaires.","Mesures cliniques et thermographiques répétées."],"limites":["Non randomisé, cohortes non concurrentes, ouvert.","Très petit effectif.","Pas de groupe témoin sans traitement."],"pratique":"Ne permet pas de conclure à un effet propre du laser."}},"title":"Thermographic outcomes of auricular laser acupuncture and auricular seed acupressure in older adults with chronic shoulder pain: an exploratory nonrandomized, nonconcurrent comparison.","journal":"Lasers Med Sci","date":"2026-10-21","doi":"10.1007/s10103-026-05078-x","abstract":[{"label":"PURPOSE","text":"Compare pain, quality of life, and cutaneous temperature changes within predefined anterior, lateral, and posterior shoulder regions of interest between auricular laser acupuncture and seed acupressure in older adults with chronic shoulder pain."},{"label":"METHODS","text":"This exploratory, nonrandomized, open-label study enrolled 20 adults aged 60-90 years, allocated by order of entry to consecutive, nonconcurrent cohorts of auricular laser acupuncture (n = 10) or seed acupressure (n = 10), treated twice weekly for five weeks. VAS, McGill, SF-36, and thermography were assessed before the first (A1) and fifth sessions (A2) and after the tenth (A3) and analyzed using linear mixed-effects models."},{"label":"RESULTS","text":"From A1 to A3, VAS decreased by - 2.70 points in Laser (95% CI - 4.37 to - 1.03) and - 2.50 in Seed (95% CI - 4.17 to - 0.83); the between-group difference was - 0.20 points (Laser - Seed; 95% CI - 2.54 to 2.14). Selected McGill and SF-36 outcomes changed; McGill affective A1-to-A2 change differed between groups (Laser - Seed: -2.70; 95% CI - 4.86 to - 0.55; p = 0.017). Anterior thermal range (ΔT) showed a TIME × GROUP interaction (p = 0.007); the A1-to-A3 between-group difference was - 1.941 °C (Seed - Laser; 95% CI - 3.097 to - 0.785), although Seed ΔT was higher at baseline (+ 1.496 °C; 95% CI 0.607 to 2.385). Lateral ΔT showed a TIME effect (p = 0.033); posterior ΔT showed none."},{"label":"CONCLUSION","text":"Clinical outcomes improved over time without evidence of differential changes between interventions. Thermography identified region-specific ΔT trajectories, warranting further investigation as a complementary method."},{"label":"CLINICAL TRIAL REGISTRATION","text":"ClinicalTrials.gov NCT07010627."}]},{"pmid":"42724412","theme":"neurologie","genere":"2026-11-08","par":"Claude","pertinent":true,"raison_exclusion":"","a_verifier":["Indiquer si possible les longueurs d'onde et protocoles des deux essais inclus (absents du résumé)."],"texte_integral":false,"fiche":{"pmid":"42724412","title_fr":"Laser-acupuncture chez l'enfant autiste : revue systématique","type":"sr","level":1,"pop":"pédiatrie","ctx":["neurodev"],"aim":"traitement","mode":["laser-acupuncture"],"nm":[],"n":76,"effect":"mitigé","theme":"Autisme","l1":"Seuls deux essais randomisés (76 enfants) existent : ils suggèrent un bénéfice de la laser-acupuncture sur les symptômes de l'autisme, avec un niveau de preuve faible à très faible.","l2":"Revue systématique (enregistrée sur PROSPERO) des essais randomisés de laser-acupuncture chez l'enfant avec trouble du spectre de l'autisme, avec une recherche dans neuf bases occidentales et asiatiques jusqu'en novembre 2024.\n\nDeux essais (76 enfants) ont été retenus ; leur hétérogénéité empêche la méta-analyse. Les enfants traités s'améliorent davantage que ceux sans traitement, sans effet indésirable rapporté, mais la qualité des preuves est jugée faible à très faible (GRADE).","l3":{"points":["Recherche large, dont bases chinoises et japonaises.","Évaluation GRADE.","Aucun effet indésirable signalé."],"limites":["Deux essais seulement, pas de méta-analyse.","Comparateur « sans traitement », pas de placebo.","Paramètres laser non détaillés dans le résumé."],"pratique":"Piste non invasive à explorer dans des essais contrôlés plus grands ; pas de recommandation possible à ce stade."}},"title":"Efficacy and Safety of Laser Acupuncture in the Treatment of Children With Autism Spectrum Disorder: A Systematic Review.","journal":"Glob Adv Integr Med Health","date":"2026-09-09","doi":"10.1177/27536130261487432","abstract":[{"label":"BACKGROUND","text":"Preliminary evidence suggests acupuncture may be helpful for pediatric autism; however, needles may be a source of healthcare trauma, so non-needle options should be prioritized."},{"label":"OBJECTIVES","text":"To conduct a systematic review (SR) to synthesize the current evidence on the efficacy and safety of laser acupuncture for pediatric autism."},{"label":"METHODS","text":"We searched the following databases from inception until Nov 14, 2024: MEDLINE, CINAHL, EMBASE, Scopus, PsycINFO, Cochrane Library, SinoMed and China National Knowledge Infrastructure and J-Stage. Randomised controlled trials of laser acupuncture on children up to age 18 years of age with ASD were included. Outcomes were autism symptoms, adverse effects and language development indicators. The PRISMA-A checklist was used to guide conduct and reporting."},{"label":"RESULTS","text":"A total of two trials (n=76) were included. The quality of evidence for most indicators were considered low to very low by GRADE criteria. Meta-analysis was not possible due to heterogeneity in populations and outcomes. Results suggest acupuncture groups benefited compared to no treatment. There were no adverse effects reported by parents of the participants in either trial."},{"label":"CONCLUSIONS","text":"Two studies indicate benefits of laser acupuncture in children with autism but given the low quality of evidence, results should be regarded with caution. Additional well conducted randomized controlled trials with larger sample sizes are required to build evidence."},{"label":"PROTOCOL REGISTRATION","text":"This protocol is registered in the International Prospective Register of Systematic Reviews (PROSPERO), registration number: CRD42024576887."}]}];
